 def __init__(self):
  self.p=MyPaintPainter(inst['brush'],{'main':sh},Wells(inst['wells']));self.L=self.p.mp.L;self.b=None
 def stroke(self,points,color):
  self.p._load(color);self.b=self.p.mbrush
  # points u,v, depth mm at the actual target image scale
  def dab(x,y,pr):self.L.rcb_stroke_to(self.b,self.p.surf['main'],float(x),float(y),float(pr/15),0.,0.,.01,0.,None)
  pts=np.array(points);delta=np.diff(pts[:,:2],axis=0);ll=np.r_[0,np.cumsum(np.linalg.norm(delta,axis=1))]
